/*
  САМОДОСТАТОЧНЫЙ диагностический скетч для ESP32 + TFT GC9A01 240x240.

  Ничего не нужно редактировать в папке библиотеки TFT_eSPI!
  Вся конфигурация пинов прописана прямо здесь, в самом скетче,
  через #define USER_SETUP_LOADED - это официальный способ TFT_eSPI
  обойти файлы User_Setup.h/User_Setup_Select.h полностью.

  Единственное условие: библиотека TFT_eSPI должна быть установлена
  через Library Manager (Инструменты -> Управление библиотеками ->
  поиск "TFT_eSPI" -> Install). Больше ничего трогать не нужно.

  Пины (ESP32):
    VCC -> 3V3
    GND -> GND
    SCL -> GPIO18
    SDA -> GPIO23
    RST -> GPIO4
    DC  -> GPIO2
    CS  -> GPIO5

  Откройте Serial Monitor на 115200 бод, залейте скетч, при необходимости
  нажмите EN (Reset) на плате, чтобы не потерять первые строки лога.
*/

// ---- Конфигурация TFT_eSPI прямо в скетче ----
#define USER_SETUP_LOADED 1

#define GC9A01_DRIVER

#define TFT_WIDTH  240
#define TFT_HEIGHT 240

#define TFT_MOSI 23
#define TFT_SCLK 18
#define TFT_CS    5
#define TFT_DC    2
#define TFT_RST   4
#define TFT_BL   -1

#define LOAD_GLCD
#define LOAD_FONT2
#define LOAD_FONT4
#define LOAD_FONT6
#define LOAD_FONT7
#define LOAD_FONT8
#define LOAD_GFXFF
#define SMOOTH_FONT

#define SPI_FREQUENCY  27000000

// ---- Дальше обычный код ----
#include <SPI.h>
#include <TFT_eSPI.h>

TFT_eSPI tft = TFT_eSPI();

void setup() {
  Serial.begin(115200);
  delay(1500);
  Serial.println();
  Serial.println("=== Диагностика TFT (самодостаточный скетч) ===");
  Serial.print("TFT_WIDTH="); Serial.print(TFT_WIDTH);
  Serial.print(" TFT_HEIGHT="); Serial.println(TFT_HEIGHT);
  Serial.print("MOSI="); Serial.print(TFT_MOSI);
  Serial.print(" SCLK="); Serial.print(TFT_SCLK);
  Serial.print(" CS="); Serial.print(TFT_CS);
  Serial.print(" DC="); Serial.print(TFT_DC);
  Serial.print(" RST="); Serial.println(TFT_RST);

  Serial.println("tft.init()...");
  tft.init();
  tft.setRotation(0);
  Serial.println("init() прошёл без зависания.");

  Serial.println("Заливка красным...");
  tft.fillScreen(TFT_RED);
  delay(2000);

  Serial.println("Заливка белым...");
  tft.fillScreen(TFT_WHITE);
  delay(2000);

  Serial.println("Зелёный квадрат в центре на чёрном фоне...");
  tft.fillScreen(TFT_BLACK);
  tft.fillRect(90, 90, 60, 60, TFT_GREEN);

  Serial.println("=== Готово ===");
}

void loop() {
  static uint16_t colors[] = {TFT_RED, TFT_GREEN, TFT_BLUE, TFT_YELLOW, TFT_MAGENTA};
  static int idx = 0;
  static uint32_t last = 0;
  if (millis() - last > 1000) {
    last = millis();
    tft.fillScreen(colors[idx]);
    Serial.print("loop(): цвет #"); Serial.println(idx);
    idx = (idx + 1) % 5;
  }
}
